text:
:root {
  --wb-black-bg: #1a0f2e; /* 极暗的紫黑色背景，像午夜城的夜空 */
  --wb-primary: #8a2be2; /* 核心的暗紫色，本官眼睛的颜色 */
  --wb-text-main: #e6e6fa; /* 柔和的淡紫色文字，不刺眼 */
}

.tm-body-char {
  color: #d8bfd8; 
  text-shadow: 0 0 5px rgba(138, 43, 226, 0.3); /* 微微的紫色荧光 */
}

